  "intro_narration": "यह आरटीआई सहायक है। मैं आपकी समस्या को समझने, सही आरटीआई प्रश्न तैयार करने, संबंधित लोक प्राधिकारी की पहचान करने और आरटीआई दाखिल करने की प्रक्रिया में आपका मार्गदर्शन करूंगा।",
  "audio_intro_full": "यह आरटीआई सहायक है। मैं आपकी समस्या को समझने, सही आरटीआई प्रश्न तैयार करने, संबंधित लोक प्राधिकारी की पहचान करने और आरटीआई दाखिल करने की प्रक्रिया में आपका मार्गदर्शन करूंगा।",
  "audio_welcome": "आरटीआई सहायक में आपका स्वागत है। मैं आपका डिजिटल सहायक हूँ। शुरू करने के लिए स्क्रीन स्पर्श करें।",
  "audio_language": "कृपया स्क्रीन और आवाज के लिए अपनी पसंदीदा भाषा चुनें।",
  "audio_signin": "अपने पंजीकृत मोबाइल नंबर और 6 अंकों के सुरक्षा पिन से लॉगिन करें।",
  "audio_signup": "अपना आरटीआई सहायक खाता बनाएं। सत्यापन कोड प्राप्त करने के लिए 10 अंकों का मोबाइल नंबर दर्ज करें।",
  "audio_verify_otp": "अपने मोबाइल पर आया 6 अंकों का ओटीपी दर्ज करें। डेमो के लिए 1 2 3 4 5 6 लिखें।",
  "audio_create_pin": "त्वरित और सुरक्षित पहुंच के लिए 6 अंकों का सुरक्षा पिन बनाएं।",
  "audio_forgot_pin": "ओटीपी सत्यापन के माध्यम से अपना सुरक्षा पिन रीसेट करें।",
  "audio_dashboard": "यह आपका नागरिक डैशबोर्ड है। आप सक्रिय आरटीआई देख सकते हैं, स्थिति जांच सकते हैं, या नया आवेदन शुरू कर सकते हैं।",
  "audio_profile": "अपनी खाता सेटिंग्स, पंजीकृत मोबाइल नंबर और सुरक्षा पिन प्रबंधित करें।",
  "audio_verify_intro": "आरटीआई कानून की धारा ३ के तहत भारत के नागरिक सूचना पा सकते हैं। आइए एक सरल डेमो सत्यापन करें।",
  "audio_verify_choose": "अपनी पसंदीदा सत्यापन विधि चुनें: सरकारी आईडी, कैमरा या डिजिलॉकर।",
  "audio_verify_aadhaar_pan": "अपना आधार या पैन नंबर दर्ज करें। डेमो ओटीपी 1 2 3 4 5 6 है।",
  "audio_verify_camera": "कृपया अपने पहचान पत्र की फोटो लें या दस्तावेज़ अपलोड करें।",
  "audio_verify_status": "आपकी पहचान भारतीय नागरिक के रूप में सत्यापित हो गई है। अब आप अपनी समस्या बता सकते हैं।",
  "audio_input_method": "आप माइक में बोल सकते हैं या स्क्रीन पर टाइप कर सकते हैं।",
  "audio_describe": "अपनी समस्या अपने शब्दों में बताएं। आप माइक में बोल सकते हैं या स्क्रीन पर लिख सकते हैं।",
  "audio_problem": "कृपया अपने शब्दों में बताएं कि क्या हुआ। अवधि, स्थान और विभाग का उल्लेख अवश्य करें।",
  "audio_we_heard": "हमने आपकी समस्या का सारांश तैयार किया है। सुनकर पुष्टि करें कि क्या यह सही है।",
  "audio_understanding": "आपकी शिकायत से हमने यह समझा है। आगे बढ़ने के लिए पुष्टि करें।",
  "audio_suitability": "आरटीआई के तहत आप सरकारी फाइलों, तारीखों और देरी के लिखित कारणों की प्रमाणित प्रतियां मांग सकते हैं।",
  "audio_questions": "हमने आपकी शिकायत के आधार पर कानूनी आरटीआई प्रश्न तैयार किए हैं। आप इन्हें सुन सकते हैं, बदल सकते हैं या आगे बढ़ सकते हैं।",
  "audio_documents": "आप डिजिलॉकर से दस्तावेज़ जोड़ सकते हैं, पीडीएफ अपलोड कर सकते हैं, या इस चरण को छोड़ सकते हैं।",
  "audio_authority": "हमने इस मामले के लिए जिम्मेदार सरकारी विभाग की पहचान कर ली है।",
  "audio_review": "कृपया जमा करने से पहले अपने आवेदन की समीक्षा करें। वैधानिक आरटीआई शुल्क 10 रुपये है।",
  "audio_payment": "यह 10 रुपये के वैधानिक आरटीआई शुल्क का डेमो भुगतान सिमुलेशन है।",
  "audio_payment_success": "भुगतान सफलतापूर्वक पूर्ण हुआ। आपका आरटीआई आवेदन संसाधित किया जा रहा है।",
