  "audio_language": "దయచేసి స్క్రీన్ మరియు వాయిస్ వివరణ కోసం మీ ప్రాధాన్యత గల భాషను ఎంచుకోండి.",
  "audio_signin": "మీ రిజిస్టర్డ్ మొబైల్ నంబర్ మరియు 6 అంకెల సెక్యూరిటీ పిన్‌తో లాగిన్ అవ్వండి.",
  "audio_signup": "మీ ఆర్టీఐ సహాయక్ ఖాతాను సృష్టించండి. ధృవీకరణ కోడ్ కోసం 10 అంకెల మొబైల్ నంబర్ నమోదు చేయండి.",
  "audio_verify_otp": "మీ మొబైల్‌కు వచ్చిన 6 అంకెల కోడ్‌ను నమోదు చేయండి. డెమో కోసం 1 2 3 4 5 6 ఉపయోగించండి.",
  "audio_create_pin": "త్వరిత మరియు సురక్షిత ప్రవేశం కోసం 6 అంకెల సెక్యూరిటీ పిన్‌ను సృష్టించండి.",
  "audio_forgot_pin": "ఓటీపీ ధృవీకరణ ద్వారా మీ సెక్యూరిటీ పిన్‌ను రీసెట్ చేయండి.",
  "audio_dashboard": "ఇది మీ సిటిజన్ డ్యాష్‌బోర్డ్. మీ దరఖాస్తులను చూడవచ్చు, స్థితిని తనిఖీ చేయవచ్చు లేదా కొత్త ఆర్టీఐ ప్రారంభించవచ్చు.",
  "audio_profile": "మీ ఖాతా సెట్టింగ్‌లు, మొబైల్ నంబర్ మరియు సెక్యూరిటీ పిన్‌ను నిర్వహించండి.",
  "audio_verify_intro": "ఆర్టీఐ చట్టం సెక్షన్ 3 ప్రకారం భారతదేశ పౌరులకు సమాచారం పొందే హక్కు ఉంది. డెమో ధృవీకరణ చేద్దాం.",
  "audio_verify_choose": "మీకు నచ్చిన ధృవీకరణ పద్ధతిని ఎంచుకోండి: ప్రభుత్వ ఐడీ, కెమెరా లేదా డిజిలాకర్.",
  "audio_verify_aadhaar_pan": "మీ ఆధార్ లేదా పాన్ నంబర్ నమోదు చేయండి. డెమో ఓటీపీ 1 2 3 4 5 6.",
  "audio_verify_camera": "దయచేసి మీ గుర్తింపు కార్డు ఫోటో తీయండి లేదా ఫైల్ అప్‌లోడ్ చేయండి.",
  "audio_verify_status": "మీ గుర్తింపు భారతీయ పౌరుడిగా ధృవీకరించబడింది. ఇప్పుడు మీ సమస్యను వివరించవచ్చు.",
  "audio_input_method": "మీరు మైక్‌లో మాట్లాడవచ్చు లేదా స్క్రీన్‌పై టైప్ చేయవచ్చు.",
  "audio_describe": "ఏమి జరిగిందో మీ మాటల్లో చెప్పండి. మైక్‌లో మాట్లాడవచ్చు లేదా స్క్రీన్‌పై టైప్ చేయవచ్చు.",
  "audio_problem": "దయచేసి ఏమి జరిగిందో వివరించండి. కాలవ్యవధి, ప్రాంతం మరియు శాఖ తెలిస్తే పేర్కొనండి.",
  "audio_we_heard": "మీ సమస్య సారాంశాన్ని తయారు చేశాము. ఇది సరైనదో కాదో విని నిర్ధారించండి.",
  "audio_understanding": "మీ ఫిర్యాదు నుండి మేము ఇది అర్థం చేసుకున్నాము. కొనసాగించడానికి నిర్ధారించండి.",
  "audio_suitability": "ఆర్టీఐ ద్వారా మీరు ప్రభుత్వ ఫైల్ రికార్డులు, ప్రాసెసింగ్ తేదీలు మరియు ఆలస్యానికి గల కారణాలను పొందవచ్చు.",
  "audio_questions": "మేము చట్టబద్ధమైన ఆర్టీఐ ప్రశ్నలను రూపొందించాము. కొనసాగే ముందు వాటిని వినవచ్చు లేదా సవరించవచ్చు.",
  "audio_documents": "మీరు డిజిలాకర్ నుండి పత్రాలను జతచేయవచ్చు, పీడీఎఫ్ అప్‌లోడ్ చేయవచ్చు లేదా ఈ దశను దాటవేయవచ్చు.",
  "audio_authority": "ఈ విషయానికి సంబంధించిన ప్రభుత్వ విభాగాన్ని మేము గుర్తించాము.",
  "audio_review": "సమర్పించే ముందు మీ దరఖాస్తును పూర్తిగా సమీక్షించండి. చట్టబద్ధమైన ఆర్టీఐ ఫీజు 10 రూపాయలు.",
  "audio_payment": "ఇది 10 రూపాయల ఆర్టీఐ ఫీజు డెమో చెల్లింపు సిమ్యులేషన్.",
  "audio_payment_success": "చెల్లింపు విజయవంతమైంది. మీ ఆర్టీఐ దరఖాస్తు ప్రాసెస్ చేయబడుతోంది.",
  "audio_payment_failure": "చెల్లింపు విఫలమైంది. మీ ఆర్టీఐ దరఖాస్తు భద్రంగా ఉంది. మీరు మళ్లీ ప్రయత్నించవచ్చు.",
  "audio_submitted": "మీ ఆర్టీఐ దరఖాస్తు పీఐవోకి విజయవంతంగా సమర్పించబడింది. రిఫరెన్స్ ఐడీ స్క్రీన్‌పై ఉంది.",
  "audio_tracking": "మీ దరఖాస్తు పురోగతిని ట్రాక్ చేయండి. సమాధానం ఇవ్వడానికి ప్రభుత్వానికి 30 రోజుల సమయం ఉంది.",
  "audio_under_review": "సమీక్షలో ఉంది అంటే అధికారి శాఖ నుండి రికార్డులను సేకరిస్తున్నారని అర్థం. మళ్లీ దరఖాస్తు చేయవద్దు.",
  "audio_first_appeal": "30 రోజుల్లో సమాధానం రాకపోతే సెక్షన్ 19(1) కింద మొదటి అప్పీల్ దాఖలు చేయవచ్చు.",
  "audio_explain_status": "మీ దరఖాస్తు స్థితి గురించి సులభమైన వివరణ ఇక్కడ ఉంది.",
