  "audio_digilocker_option": "ఇది డిజిలాకర్ ఎంపిక. మీ గుర్తింపును ధృవీకరించడానికి లేదా అవసరమైన పత్రాలను డిజిటల్ రూపంలో పొందడానికి డిజిలాకర్ ఉపయోగపడుతుంది. మీరు దీనితో కొనసాగవచ్చు.",
