  "appealEligibleNotice": "நீங்கள் முதல் மேல்முறையீடு செய்ய தகுதியுடையவர். ஆரம்பத்தில் விண்ணப்பித்து 30 நாட்களுக்கு மேலாகியும் முழுமையான தகவல்கள் வரவில்லை.",
  "appealIneligibleNotice": "சட்டப்பூர்வ 30 நாள் கால அவகாசம் இன்னும் முடிவடையவில்லை. பொதுவாக 30 நாட்கள் முடிந்த பின்னரே முதல் மேல்முறையீடு செய்யப்படுகிறது.",
