  "appealGroundFeeDesc": "பிஐஓ தேவையற்ற அல்லது மிக அதிகமான கூடுதல் கட்டணத்தைக் கோரியுள்ளார்.",
  "appealFactsLabel": "மேல்முறையீட்டின் உண்மை விவரங்கள்",
  "appealFactsPlaceholder": "விண்ணப்பித்த தேதிகளைக் குறிப்பிட்டு, பிஐஓ எவ்வாறு முழுமையான தகவல்களை வழங்கத் தவறினார் என்பதை விவரிக்கவும்…",
  "appealPrayerLabel": "கோரப்படும் பரிகாரம் / நிவாரணம்",
  "appealPrayerPlaceholder": "முதல் மேல்முறையீட்டு அதிகாரியிடம் நீங்கள் கோரும் ஆவணங்கள் அல்லது வழிகாட்டுதல்களைக் குறிப்பிடவும்…",
  "appealStatementTitle": "மேல்முறையீட்டு அறிக்கை மற்றும் நிவாரணம்",
  "appealStatementDesc": "குறிப்பிட்ட விவரங்களையும் மேல்முறையீட்டு அதிகாரியிடம் நீங்கள் கோரும் நிவாரணத்தையும் வழங்கவும்.",
  "appealFaaLabel": "முதல் மேல்முறையீட்டு அதிகாரி:",
  "appealReviewSummaryBtn": "மேல்முறையீட்டுச் சுருக்கத்தை மதிப்பாய்வு செய்க →",
  "appealReviewTitle": "முதல் மேல்முறையீட்டு மனுவை மதிப்பாய்வு செய்யவும்",
  "appealReviewDesc": "சமர்ப்பிக்கும் முன் அனைத்து மேல்முறையீட்டு விவரங்களையும் சரிபார்க்கவும்.",
