  "intro_narration": "ಇದು ಆರ್‌ಟಿಐ ಸಹಾಯಕ. ನಿಮ್ಮ ಸಮಸ್ಯೆಯನ್ನು ಅರ್ಥಮಾಡಿಕೊಳ್ಳಲು, ಸರಿಯಾದ ಆರ್‌ಟಿಐ ಪ್ರಶ್ನೆಗಳನ್ನು ರೂಪಿಸಲು, ಸೂಕ್ತವಾದ ಸಾರ್ವಜನಿಕ ಪ್ರಾಧಿಕಾರವನ್ನು ಗುರುತಿಸಲು ಮತ್ತು ಆರ್‌ಟಿಐ ಸಲ್ಲಿಸುವ ಪ್ರಕ್ರಿಯೆಯಲ್ಲಿ ನಿಮಗೆ ಮಾರ್ಗದರ್ಶನ ನೀಡುತ್ತೇನೆ.",
  "audio_intro_full": "ಇದು ಆರ್‌ಟಿಐ ಸಹಾಯಕ. ನಿಮ್ಮ ಸಮಸ್ಯೆಯನ್ನು ಅರ್ಥಮಾಡಿಕೊಳ್ಳಲು, ಸರಿಯಾದ ಆರ್‌ಟಿಐ ಪ್ರಶ್ನೆಗಳನ್ನು ರೂಪಿಸಲು, ಸೂಕ್ತವಾದ ಸಾರ್ವಜನಿಕ ಪ್ರಾಧಿಕಾರವನ್ನು ಗುರುತಿಸಲು ಮತ್ತು ಆರ್‌ಟಿಐ ಸಲ್ಲಿಸುವ ಪ್ರಕ್ರಿಯೆಯಲ್ಲಿ ನಿಮಗೆ ಮಾರ್ಗದರ್ಶನ ನೀಡುತ್ತೇನೆ.",
  "audio_welcome": "ಆರ್‌ಟಿಐ ಸಹಾಯಕಕ್ಕೆ ಸುಸ್ವಾಗತ. ನಾನು ನಿಮ್ಮ ಡಿಜಿಟಲ್ ಸಹಾಯಕ. ಪ್ರಾರಂಭಿಸಲು ಸ್ಕ್ರೀನ್ ಸ್ಪರ್ಶಿಸಿ.",
