const DICTS: Record<Lang, Dict> = { en, hi, te, ta, kn, ml, bn, mr };

export function t(lang: Lang, key: string): string {
  const dict = DICTS[lang] || DICTS.en;
  return dict[key] ?? DICTS.en[key] ?? key;
}
